import { FormEvent, useState } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
  initialSettings?: ProfileSettings;
}

function ProfileSettingsForm({ onSave, initialSettings }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? true,
  );

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'flex', flexDirection: 'column', gap: '16px', fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxInputField
        label="Имя"
        required
        value={name}
        onChange={(event) => setName(event.target.value)}
        placeholder="Как к вам обращаться"
      />

      <JxSelect
        label="Язык интерфейса"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={language}
        onValueChange={setLanguage}
      />

      <JxSwitch
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary" disabled={name.trim().length === 0}>
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

export default ProfileSettingsForm;

